    } catch (agentError) {
      try {
        return await fetchEvaluationById(id);
      } catch (_evalError) {
        throw agentError;
      }
    }
  }
  try {
    return await fetchEvaluationById(id);
  } catch (evalError) {
    try {
      return await fetchAgentById(id, item);
    } catch (_agentError) {
      throw evalError;
    }
