import { JSDOM } from "jsdom";
import fs from "node:fs";
import path from "node:path";

const SCRIPT = "/home/user/chat-archive/Arena.ai - LMSYS Arena Chat Exporter-2.3.2.user.js";
const source = fs.readFileSync(SCRIPT, "utf8");

const EVAL_A = "019c4323-cbf3-7648-bf96-c1ae90af38cf"; // active chat
const EVAL_B = "019c3dcc-11d3-7739-841e-db79ba4bf808"; // archived chat
const EVAL_C = "019c4315-afd0-7b86-9f2f-d5eb25264ef9"; // archived chat
const AGENT_A = "01a1014c-c144-7924-902d-9f93a8ca22ca"; // archived agent chat
const AGENT_B = "01a1014c-bd83-773f-b055-b4f6d22c9f9e"; // active agent chat

const dom = new JSDOM(
  `<!doctype html><html><head></head><body><div id="app">arena.ai search page</div></body></html>`,
  { url: "https://arena.ai/search", runScripts: "outside-only", pretendToBeVisual: true }
);
const { window } = dom;

const calls = [];
const blobs = [];
let zipEntries = null;

function evaluationPayload(id, { title, archivedAt, mode = "side_by_side" }) {
  return {
    id,
    userId: "11111111-2222-3333-4444-555555555555",
    title,
    mode,
    visibility: "private",
    lastMessageIds: [],
    archivedAt: archivedAt || null,
    deletedAt: null,
    deletionPendingProcessing: null,
    createdAt: "2026-09-20T10:00:00.000Z",
    updatedAt: "2026-09-21T11:00:00.000Z",
    messages: [
      { id: `${id}-m1`, role: "user", content: "hello there", createdAt: "2026-09-20T10:00:00.000Z" },
      {
        id: `${id}-m2`,
        role: "assistant",
        content: "general kenobi",
        createdAt: "2026-09-20T10:00:05.000Z",
        modelName: "gpt-5",
      },
    ],
    maskedEvaluations: [],
    pairwiseFeedbacks: [],
    pointwiseFeedbacks: [],
    revealedModels: [],
  };
}

const historyPages = {
  "": {
    entries: [
      { type: "evaluation", id: EVAL_A, title: "Active chat", mode: "side_by_side", createdAt: "2026-09-30T09:00:00.000Z", updatedAt: "2026-09-30T10:00:00.000Z", archivedAt: null },
      { type: "agentic", id: AGENT_A, title: "Archived agent chat", createdAt: "2026-09-01T09:00:00.000Z", updatedAt: "2026-09-02T10:00:00.000Z", archivedAt: "2026-09-03T12:00:00.000Z", productMode: "coding", codingSessionStatus: "active" },
    ],
    pagination: { hasMore: true, cursor: "cursor-1", limit: 20 },
  },
  "cursor-1": {
    entries: [
      { type: "evaluation", id: EVAL_B, title: "Archived chat B", mode: "battle", createdAt: "2026-09-10T09:00:00.000Z", updatedAt: "2026-09-11T10:00:00.000Z", archivedAt: "2026-09-12T12:00:00.000Z" },
      { type: "evaluation", id: EVAL_C, title: "Archived chat C", mode: "battle", createdAt: "2026-09-13T09:00:00.000Z", updatedAt: "2026-09-14T10:00:00.000Z", archivedAt: "2026-09-15T12:00:00.000Z" },
      { type: "agentic", id: AGENT_B, title: "Active agent chat", createdAt: "2026-09-16T09:00:00.000Z", updatedAt: "2026-09-17T10:00:00.000Z", archivedAt: null, productMode: "coding", codingSessionStatus: "active" },
    ],
    pagination: { hasMore: false, cursor: null, limit: 20 },
  },
};

window.fetch = async (url) => {
  const href = String(url);
  calls.push(href);
  const parsed = new URL(href, "https://arena.ai");
  if (parsed.pathname === "/api/history/unified") {
    const cursor = parsed.searchParams.get("cursor") || "";
    const body = historyPages[cursor];
    if (!body) throw new Error(`unexpected cursor ${cursor}`);
    if ((parsed.searchParams.get("archivedOnly") || "false") === "true" && !parsed.searchParams.get("archivedOnly")) {
      throw new Error("archivedOnly flag lost");
    }
    return jsonResponse(body);
  }
  const evalMatch = parsed.pathname.match(/^\/api\/evaluation\/([0-9a-f-]{36})$/);
  if (evalMatch) {
    const id = evalMatch[1];
    const archived = id === EVAL_B || id === EVAL_C || id === AGENT_A;
    return jsonResponse(
      evaluationPayload(id, {
        title: archived ? `Archived chat ${id.slice(0, 4)}` : `Active chat ${id.slice(0, 4)}`,
        archivedAt: archived ? "2026-09-12T12:00:00.000Z" : null,
      })
    );
  }
  if (parsed.pathname.startsWith("/agent/") || parsed.pathname.startsWith("/c/")) {
    return textResponse("<html><head><title>Arena</title></head><body>no flight payload</body></html>");
  }
  throw new Error(`unexpected fetch ${href}`);
};
window.fetch = new Proxy(window.fetch, { apply: (t, thisArg, args) => t(...args) });

function jsonResponse(data) {
  return {
    ok: true,
    status: 200,
    statusText: "OK",
    json: async () => JSON.parse(JSON.stringify(data)),
    text: async () => JSON.stringify(data),
  };
}
function textResponse(text) {
  return {
    ok: true,
    status: 200,
    statusText: "OK",
    json: async () => JSON.parse(text),
    text: async () => text,
  };
}

window.fflate = {
  strToU8: (s) => new TextEncoder().encode(s),
  zipSync: (entries) => {
    zipEntries = entries;
    return new Uint8Array([1, 2, 3]);
  },
};
window.URL.createObjectURL = (blob) => {
  blobs.push(blob);
  return `blob:fake-${blobs.length}`;
};
window.URL.revokeObjectURL = () => {};

const OriginalBlob = window.Blob;
window.Blob = class CapturingBlob extends OriginalBlob {
  constructor(parts, options) {
    super(parts, options);
    this.__parts = parts;
  }
};

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function waitFor(predicate, label, timeout = 4000) {
  const started = Date.now();
  for (;;) {
    if (predicate()) return;
    if (Date.now() - started > timeout) throw new Error(`timeout waiting for ${label}`);
    await sleep(20);
  }
}

const results = [];
function check(label, condition, extra = "") {
  results.push({ label, ok: Boolean(condition), extra });
  console.log(`${condition ? "PASS" : "FAIL"}  ${label}${extra ? `  ${extra}` : ""}`);
  if (!condition) process.exitCode = 1;
}

window.eval(source);

const document = window.document;
const $ = (sel) => document.querySelector(sel);
const dock = $("#arena-chat-export-dock-btn");
check("GUI mounted (dock button present)", Boolean(dock));
dock.click();
await sleep(10);
const panel = $("#arena-chat-export-panel");
check("panel opens", panel?.getAttribute("data-open") === "true");
check("scope selector defaults to all", $('[data-role="history-scope"]')?.value === "all");

// --- fetch list (default scope: active + archived) ---
calls.length = 0;
$('[data-role="fetch-history"]').click();
await waitFor(() => $("#arena-chat-export-status")?.textContent.includes("Loaded"), "history fetch");
const statusText = $("#arena-chat-export-status").textContent;
check("status reports archived count", statusText.includes("Loaded 5 conversations (3 archived)."), statusText);
check(
  "first request includes includeArchived=true and no archivedOnly",
  calls[0].includes("includeArchived=true") && !calls[0].includes("archivedOnly"),
  calls[0]
);
check("pagination follows cursor", calls.length === 2 && calls[1].includes("cursor=cursor-1"), calls[1] || "");

const renderedItems = document.querySelectorAll('[data-role="history-list"] .item');
check("all 5 conversations rendered", renderedItems.length === 5, `rendered=${renderedItems.length}`);
const archivedRows = document.querySelectorAll('[data-role="history-list"] .item[data-archived="true"]');
check("3 archived rows marked", archivedRows.length === 3, `archived rows=${archivedRows.length}`);
const badges = document.querySelectorAll('[data-role="history-list"] .badge');
check("archived badges rendered", badges.length === 3 && badges[0].textContent.startsWith("archived"), badges[0]?.textContent || "");

// --- save list JSON ---
blobs.length = 0;
$('[data-role="download-list"]').click();
await waitFor(() => $("#arena-chat-export-status")?.textContent.includes("Conversation list saved"), "list save");
const listBlob = blobs[blobs.length - 1];
const listPayload = JSON.parse(String(listBlob.__parts[0]));
check("list JSON scope=all", listPayload.scope === "all", JSON.stringify(listPayload.counts));
check("list JSON counts archived=3", listPayload.counts.total === 5 && listPayload.counts.archived === 3 && listPayload.counts.active === 2, JSON.stringify(listPayload.counts));
check("list JSON keeps archivedAt", listPayload.items.filter((i) => i.archivedAt).length === 3);

// --- archived-only scope ---
const scopeSelect = $('[data-role="history-scope"]');
scopeSelect.value = "archived";
scopeSelect.dispatchEvent(new window.Event("change", { bubbles: true }));
calls.length = 0;
$('[data-role="fetch-history"]').click();
await waitFor(() => $("#arena-chat-export-status")?.textContent.includes("Loaded"), "archived fetch");
check("archived scope sends archivedOnly=true", calls[0].includes("archivedOnly=true"), calls[0]);
check("archived scope keeps includeArchived=false", calls[0].includes("includeArchived=false"), calls[0]);

// --- batch export (JSON) with archived items selected ---
zipEntries = null;
$('[data-role="select-all"]').click();
await sleep(10);
$('[data-role="export-selected-json"]').click();
await waitFor(() => $("#arena-chat-export-status")?.textContent.includes("Batch export finished"), "batch export", 8000);
const manifestBytes = zipEntries?.["manifest.json"];
check("zip contains manifest.json", Boolean(manifestBytes));
const manifest = JSON.parse(new TextDecoder().decode(manifestBytes));
check("manifest archivedCount=3 (5 selected)", manifest.selectedCount === 5 && manifest.archivedCount === 3, JSON.stringify({ selected: manifest.selectedCount, archived: manifest.archivedCount }));
check("manifest listScope=archived", manifest.listScope === "archived", String(manifest.listScope));
check("manifest selectedItems carry archivedAt", manifest.selectedItems.filter((i) => i.archivedAt).length === 3, JSON.stringify(manifest.selectedItems[0]));
check("all 5 items exported", manifest.successCount === 5 && manifest.failedCount === 0, JSON.stringify(manifest.failedExports));
const jsonEntryName = Object.keys(zipEntries).find((n) => n.endsWith(".json") && n !== "manifest.json");
const exportedJson = JSON.parse(new TextDecoder().decode(zipEntries[jsonEntryName]));
check("exported JSON keeps archivedAt", "archivedAt" in exportedJson, jsonEntryName);

// --- TXT export shows the Archived header for one archived chat ---
zipEntries = null;
$('[data-role="clear-selection"]').click();
await sleep(10);
const rows = [...document.querySelectorAll('[data-role="history-list"] .item')];
const archivedRow = rows.find((row) => row.getAttribute("data-archived") === "true");
archivedRow.querySelector('input[type="checkbox"]').click();
await sleep(10);
$('[data-role="export-selected-txt"]').click();
await waitFor(() => $("#arena-chat-export-status")?.textContent.includes("Batch export finished"), "txt export", 8000);
const txtEntryName = Object.keys(zipEntries).find((n) => n.endsWith(".txt"));
const exportedTxt = new TextDecoder().decode(zipEntries[txtEntryName]);
check("TXT header contains 'Archived :'", /^Archived :/m.test(exportedTxt), txtEntryName);
check("TXT body preserved", exportedTxt.includes("general kenobi"));

// --- legacy console API still works and carries archivedAt ---
blobs.length = 0;
const legacyName = await window.__arenaChatExport(EVAL_B, "json", "evaluation");
await waitFor(() => blobs.length > 0, "legacy export");
const legacyPayload = JSON.parse(String(blobs[blobs.length - 1].__parts[0]));
check("__arenaChatExport still works", typeof legacyName === "string" && legacyPayload.recordType === "evaluation");
check("legacy JSON includes archivedAt", legacyPayload.archivedAt === "2026-09-12T12:00:00.000Z", String(legacyPayload.archivedAt));

