### Request policy

```js
  const REQUEST_TIMEOUT_MS = 120000;
  const REQUEST_MAX_ATTEMPTS = 3;
  const RETRY_BACKOFF_MS = [800, 2500];
  const RETRY_STATUSES = new Set([408, 425, 429, 500, 502, 503, 504]);

  async function fetchWithPolicy(url, options) {
    const { retries = REQUEST_MAX_ATTEMPTS, ...init } = options || {};
    let lastError = null;
    for (let attempt = 1; attempt <= retries; attempt += 1) {
      const controller = typeof AbortController === "function" ? new AbortController() : null;
      let timedOut = false;
      const timer = controller
        ? window.setTimeout(() => { timedOut = true; controller.abort(); }, REQUEST_TIMEOUT_MS)
        : null;
      try {
        const response = await fetch(url, { ...init, signal: controller ? controller.signal : undefined });
        if (timer) window.clearTimeout(timer);
        if (RETRY_STATUSES.has(response.status) && attempt < retries) {
          await wait(backoffDelay(attempt));
          continue;
        }
        return response;
      } catch (error) {
        if (timer) window.clearTimeout(timer);
        lastError = timedOut ? new Error(t("request_timeout", { seconds: Math.round(REQUEST_TIMEOUT_MS / 1000) })) : error;
        if (attempt < retries) {
          await wait(backoffDelay(attempt));
          continue;
        }
      }
    }
    throw lastError || new Error(t("request_failed_generic"));
  }
```
