### Concurrency pool

```js
  function normalizeConcurrency(value) {
    const number = Math.floor(Number(value));
    if (!Number.isFinite(number) || number < 1) return 1;
    return Math.min(number, EXPORT_CONCURRENCY_MAX);
  }

  async function runPool(total, concurrency, worker) {
    const limit = Math.max(1, Math.min(normalizeConcurrency(concurrency), total || 1));
    let nextIndex = 0;
    let firstError = null;
    const runners = new Array(limit).fill(0).map(async () => {
      while (true) {
        const index = nextIndex;
        nextIndex += 1;
        if (index >= total) return;
        try {
          await worker(index);
        } catch (error) {
          if (!firstError) firstError = error;
          return;
        }
      }
    });
    await Promise.all(runners);
    return firstError;
  }
```
