```js
  async function exportBatchConversations(conversationItems, formats, hooks, manifestExtras, options) {
    const items = normalizeExportItems(conversationItems);
    if (!items.length) throw new Error(t("no_selected_items"));
    const formatList = (Array.isArray(formats) ? formats : [formats])
      .map((f) => String(f || "").toLowerCase())
      .filter((f, i, all) => (f === "json" || f === "txt") && all.indexOf(f) === i);
    if (!formatList.length) throw new Error(t("unknown_export_format", { format: String(formats) }));

    const zipLib = getZipLib();
    const concurrency = normalizeConcurrency(options?.concurrency ?? EXPORT_CONCURRENCY_DEFAULT);
    const usedNames = new Set();
    const archiveEntries = {};            // fallback (non-streaming) storage
    const zipStream = createZipStream(zipLib, options);  // { add(name, text), finish() -> Blob|Uint8Array|null, streaming: bool }
    const archivedCount = items.filter((item) => Boolean(item?.archivedAt)).length;
    const outcomes = new Array(items.length);
    let completed = 0;
    let successCount = 0;
    let failedCount = 0;
    const startedAt = Date.now();

    await runPool(items.length, concurrency, async (index) => {
      // small jitter so parallel workers do not fire in lockstep
      await wait(20 + Math.floor(Math.random() * 60));
      const item = items[index];
      hooks?.onItemStart?.({ index: index + 1, total: items.length, item });
      try {
        const record = await fetchExportRecord(item);
        const files = {};
        for (const format of formatList) {
          const payload = getExportPayload(record, format);
          const nextName = uniqueName(usedNames, payload.fileName);
          await zipStream.add(nextName, payload.textContent);
          files[format] = nextName;
        }
        outcomes[index] = {
          ok: true,
          entry: {
            fileName: files[formatList[0]],
            files,
            conversationId: String(record?.id || item?.id || ""),
            recordType: isAgentExportObject(record) ? "agentic" : "evaluation",
            title: String(record?.title || item?.title || "").trim() || null,
            archivedAt: item?.archivedAt || null,
          },
        };
        successCount += 1;
      } catch (error) {
        outcomes[index] = {
          ok: false,
          entry: {
            conversationId: String(item?.id || ""),
            recordType: item?.type || "unknown",
            title: String(item?.title || "").trim() || null,
            archivedAt: item?.archivedAt || null,
          },
        };
        failedCount += 1;
        warn("item export failed", item?.id, item?.type, item?.title, error);
        hooks?.onItemError?.({ index: index + 1, total: items.length, item, error });
      } finally {
        completed += 1;
        hooks?.onProgress?.({
          index: completed,
          total: items.length,
          successCount,
          failedCount,
          elapsedMs: Date.now() - startedAt,
        });
      }
    });

    const successfulExports = outcomes.filter((o) => o?.ok).map((o) => o.entry);
    const failedExports = outcomes.filter((o) => o && !o.ok).map((o) => o.entry);

    const manifest = { ... same but successfulExports/failedExports ... };
    await zipStream.add("manifest.json", `${JSON.stringify(manifest, null, 2)}\n`);

    hooks?.onZipProgressStart?.({ total: items.length, successCount, failedCount });
    const finished = await zipStream.finish();
    const zipFileName = buildZipFileName(formatList, options);
    downloadBlob(zipFileName, "application/zip", finished);
    return { total: items.length, successCount, failedCount, packaged: true, manifestOnly: successCount === 0, fileName: zipFileName };
  }
