  function uniqueName(usedNames, desired) {
    let nextName = desired;
    if (usedNames.has(nextName)) { ...suffix logic... }
    usedNames.add(nextName);
    return nextName;
  }

  function createZipStream(zipLib, options) {
    const level = Number.isFinite(options?.compressionLevel) ? options.compressionLevel : 6;
    const streamSupported = typeof zipLib.Zip === "function" && typeof zipLib.ZipDeflate === "function";
    if (!streamSupported) {
      const entries = {};
      return {
        streaming: false,
        async add(name, text) { entries[name] = zipLib.strToU8(text); },
        async finish() { return zipLib.zipSync(entries, { level }); },
      };
    }
    const chunks = [];
    let error = null;
    const zip = new zipLib.Zip((err, chunk, final) => {
      if (err) { error = err; return; }
      if (chunk) chunks.push(chunk);
    });
    return {
      streaming: true,
      async add(name, text) {
        const file = new zipLib.ZipDeflate(name, { level });
        zip.add(file);
        file.push(zipLib.strToU8(text), true);
      },
      async finish() {
        zip.end();
        if (error) throw error;
        return new Blob(chunks, { type: "application/zip" });
      },
    };
  }
```
