    for (let attempt = 1; attempt <= attempts; attempt += 1) {
      const timeoutMs = getRequestTimeoutMs();
      const controller = typeof AbortController === "function" ? new AbortController() : null;
      let timedOut = false;
      const timer = controller
        ? window.setTimeout(() => {
            timedOut = true;
            controller.abort();
          }, timeoutMs)
        : null;
      try {
        const response = await fetch(url, {
          ...(options || {}),
          attempts: undefined,
          signal: controller ? controller.signal : undefined,
        });
        if (timer) window.clearTimeout(timer);
        if (RETRY_STATUSES.has(response.status) && attempt < attempts) {
          log("retrying", response.status, `attempt ${attempt}/${attempts}`, url);
          await wait(backoffDelay(attempt));
          continue;
        }
        return response;
      } catch (error) {
        if (timer) window.clearTimeout(timer);
        lastError = timedOut
          ? new Error(t("request_timeout", { seconds: Math.round(timeoutMs / 1000) }))
          : error;
        if (attempt < attempts) {
          log("retrying after error", toErrorMessage(lastError), `attempt ${attempt}/${attempts}`, url);
          await wait(backoffDelay(attempt));
          continue;
        }
      }
    }
    throw lastError || new Error(t("unknown_error"));
  }
```
Note: `options` includes `method`, `credentials`, `headers`; spreading is fine. `attempts: undefined` — spreading with undefined value adds key with undefined → fetch ignores unknown keys. Actually `{...options, attempts: undefined}` sets the property to undefined; fetch's RequestInit ignores unknown props. Fine, but cleaner to strip: use destructuring:
```js
        const { attempts: _attempts, ...init } = options || {};
        const response = await fetch(url, { ...init, signal: ... });
```
