def walk(a, b, path=""):
    out = []
    if type(a) != type(b):
        out.append((path, f"type {type(a).__name__} -> {type(b).__name__}"))
        return out
    if isinstance(a, dict):
        for k in sorted(set(a) | set(b)):
            if k not in a: out.append((f"{path}.{k}", "added"))
            elif k not in b: out.append((f"{path}.{k}", "removed"))
            else: out += walk(a[k], b[k], f"{path}.{k}")
    elif isinstance(a, list):
        if len(a) != len(b):
            out.append((f"{path}[len]", f"{len(a)} -> {len(b)}"))
        for i, (x, y) in enumerate(zip(a, b)):
            out += walk(x, y, f"{path}[{i}]")
    elif a != b:
        sa, sb = str(a), str(b)
        if len(sa) > 90 or len(sb) > 90:
            out.append((path, f"CHANGED ({len(sa)} -> {len(sb)} chars): {sa[:70]!r} -> {sb[:70]!r}"))
